 "content": "def transform(grid):
    """Fill with 4 the overlap of the top and bottom color bars above the 2 divider."""
    out = [row[:] for row in grid]
    if not grid:
        return out
    divider = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), None)
    if divider is None:
        return out
    top = grid[0]
    bottom = grid[-1]
    marker = next((v for v in top if v != 0), 0)
    if marker == 0 or any(v != 0 and v != marker for v in top) or any(v != 0 and v != marker for v in bottom):
        return out
    for c, (a, b) in enumerate(zip(top, bottom)):
        if a == marker and b == marker:
            for r in range(1, divider):
                if out[r][c] == 0:
                    out[r][c] = 4
    return out
